  var STOPWORDS = new Set(["a", "about", "after", "against", "all", "among", "an", "and", "any", "are", "around", "as", "at", "be", "been", "before", "being", "between", "both", "but", "by", "can", "did", "do", "does", "doesn't", "doing", "don't", "during", "each", "few", "for", "from", "had", "has", "have", "having", "he", "her", "him", "his", "how", "i", "if", "in", "into", "is", "it", "its", "just", "like", "me", "more", "most", "my", "no", "nor", "not", "now", "of", "on", "only", "or", "other", "our", "out", "over", "own", "s", "same", "she", "should", "so", "some", "such", "t", "than", "that", "the", "their", "them", "then", "these", "they", "this", "those", "through", "to", "too", "under", "us", "very", "was", "we", "were", "what", "when", "where", "which", "who", "whom", "why", "will", "with", "without", "you", "your"]);
