    var toggleIcon = el("span", "gf-pot-icon", POT_SVG);
    toggle.appendChild(toggleIcon);
    toggle.appendChild(el("span", "gf-chat-toggle-label", "Chat"));

    var teaser = el("div", "gf-chat-teaser");
